Object.assign(SNIP,{"l51cu": "#include <future>\nlong long tong(int a, int b);\nfuture<long long> f = async(launch::async, tong, 1, 1000);  // chạy tong ở luồng khác\n// ... main làm việc khác ...\nlong long kq = f.get();     // chờ (nếu chưa xong) rồi lấy kết quả; get() chỉ gọi MỘT lần"});PRESET_NOTES["l51"]={"Ví dụ: async và get": "async khởi động tong(1, 10) ở một luồng mới và trả ngay về future f; main in dòng của mình. f.get() chờ tác vụ xong rồi trả về 55.", "Ví dụ: nhiều tác vụ với vector<future>": "Ba tác vụ chạy song song, mỗi tác vụ cộng một đoạn. main lấy kết quả từng future theo thứ tự; không có biến dùng chung nên không cần khóa, cũng không phải join.", "Ví dụ: ngoại lệ truyền qua get": "Tác vụ thứ hai ném runtime_error ở luồng của nó. Ngoại lệ không làm dừng chương trình mà được cất trong f2, rồi ném lại đúng ở chỗ main gọi f2.get(), nên catch của main bắt được.", "Ví dụ: launch::deferred": "Với deferred, binhPhuong chưa chạy khi tạo future (cột của tác vụ ghi “chưa chạy”); nó chỉ chạy khi main gọi get(), nên dòng “dang tinh” in ra sau dòng “chua tinh gi ca”.", "Lỗi: gọi get() hai lần": "Lần get() đầu đã lấy kết quả ra khỏi future; lần hai không còn gì nên ném future_error và chương trình dừng. Cần dùng lại thì lưu kết quả vào một biến: int kq = f.get();"};EX_HINTS["l51"]=[["async(launch::async, tongLe, 1, n / 2) trả về future<long long>.", "Lưu kết quả get() vào biến, đừng gọi get() hai lần."], ["cref(v) cho các tác vụ đọc chung v mà không chép; chỉ đọc nên không cần khóa.", "Mỗi f.get() trả về đúng kiểu của hàm."], ["Ngoại lệ ném trong tác vụ được ném lại ở f.get().", "Một catch (const exception& e) bắt được cả hai loại."]];
/* ===================== BÀI 51 · async / future ===================== */
/* Bài 51 · async / future
   Sinh bởi công cụ soạn bài: ví dụ cho trình mô phỏng (kèm hình động), bài tập chấm tự động.
   Trắc nghiệm ở quiz.json, gợi ý ở hints.json, lời giải ở solutions/ (nội dung bảo vệ). */
const P51=[{label:"Ví dụ: async và get",input:"",code:"#include <iostream>\n#include <future>\nusing namespace std;\n\nlong long tong(int a, int b) {\n    long long s = 0;\n    for (int i = a; i <= b; i++) {\n        s += i;\n    }\n    return s;\n}\nint main() {\n    future<long long> f = async(launch::async, tong, 1, 10);\n    cout << \"main lam viec khac...\\n\";\n    long long kq = f.get();\n    cout << \"Ket qua: \" << kq << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"}]},{label:"Ví dụ: nhiều tác vụ với vector<future>",input:"",code:"#include <iostream>\n#include <future>\n#include <vector>\nusing namespace std;\n\nlong long tong(int a, int b) {\n    long long s = 0;\n    for (int i = a; i <= b; i++) {\n        s += i;\n    }\n    return s;\n}\nint main() {\n    vector<future<long long>> ds;\n    for (int k = 0; k < 3; k++) {\n        ds.push_back(async(launch::async, tong, k * 10 + 1, k * 10 + 10));\n    }\n    long long t = 0;\n    for (auto& f : ds) {\n        t += f.get();\n    }\n    cout << \"Tong 1..30 = \" << t << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"}]},{label:"Ví dụ: ngoại lệ truyền qua get",input:"",code:"#include <iostream>\n#include <future>\n#include <stdexcept>\nusing namespace std;\n\nint chia(int a, int b) {\n    if (b == 0) throw runtime_error(\"chia cho 0\");\n    return a / b;\n}\nint main() {\n    auto f1 = async(launch::async, chia, 10, 2);\n    auto f2 = async(launch::async, chia, 1, 0);\n    cout << \"10 / 2 = \" << f1.get() << \"\\n\";\n    try {\n        cout << f2.get() << \"\\n\";\n    } catch (const exception& e) {\n        cout << \"Loi tu luong khac: \" << e.what() << \"\\n\";\n    }\n    return 0;\n}",viz:[{type:"threads"}]},{label:"Ví dụ: launch::deferred",input:"",code:"#include <iostream>\n#include <future>\nusing namespace std;\n\nint binhPhuong(int x) {\n    cout << \"  (dang tinh \" << x << \")\\n\";\n    return x * x;\n}\nint main() {\n    future<int> f = async(launch::deferred, binhPhuong, 7);\n    cout << \"Da tao future, chua tinh gi ca\\n\";\n    cout << \"Ket qua: \" << f.get() << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"}]},{label:"Lỗi: gọi get() hai lần",input:"",code:"#include <iostream>\n#include <future>\nusing namespace std;\n\nint tang(int x) {\n    return x + 1;\n}\nint main() {\n    future<int> f = async(launch::async, tang, 5);\n    cout << f.get() << \"\\n\";\n    cout << f.get() << \"\\n\";\n    return 0;\n}",viz:[{type:"threads"}]}];
const sim51=makeSim2(document.getElementById("sim-l51"),{id:"s51",presets:P51});
makeEx2(document.getElementById("ex-l51"),sim51,[{t:"Hai nửa bằng async",d:"Nhập n (2 ≤ n ≤ 400). Dùng hai <code>async<\/code> tính tổng các số lẻ trong [1, n/2] và trong [n/2 + 1, n]. In hai tổng và tổng chung, mỗi số một dòng.",tests:[{in:"10",out:"9\n16\n25"},{in:"2",out:"1\n0\n1"},{in:"7",out:"4\n12\n16"}],start:"#include <iostream>\n#include <future>\nusing namespace std;\n\nlong long tongLe(int a, int b) {\n    long long s = 0;\n    for (int i = a; i <= b; i++)\n        if (i % 2 != 0) s += i;\n    return s;\n}\nint main() {\n    int n;\n    cin >> n;\n    // auto f1 = async(...), f2 = async(...);\n    return 0;\n}",need:/async\s*\([\s\S]*async\s*\(/,needMsg:"Hãy dùng hai lời gọi async."},{t:"Nhiều thống kê song song",d:"Nhập n và n số nguyên. Chạy ba tác vụ async song song: tính tổng, tìm số lớn nhất, đếm số âm (mỗi tác vụ là một hàm nhận <code>const vector&lt;int&gt;&amp;<\/code>, truyền bằng <code>cref<\/code>). In ba kết quả, mỗi kết quả một dòng.",tests:[{in:"5\n3 -1 7 -4 2",out:"7\n7\n2"},{in:"1\n-9",out:"-9\n-9\n1"}],start:"#include <iostream>\n#include <future>\n#include <vector>\nusing namespace std;\n\nlong long tong(const vector<int>& v) { return 0; }\nint lonNhat(const vector<int>& v) { return 0; }\nint demAm(const vector<int>& v) { return 0; }\nint main() {\n    int n;\n    cin >> n;\n    vector<int> v(n);\n    for (int& x : v) cin >> x;\n    // auto f1 = async(launch::async, tong, cref(v)); ...\n    return 0;\n}",need:/async[\s\S]*async[\s\S]*async/,needMsg:"Hãy dùng ba lời gọi async."},{t:"Kiểm tra dữ liệu ở luồng khác",d:"Viết <code>int kiemTra(int x)<\/code>: nếu x &lt; 0 thì ném <code>invalid_argument(\"so am\")<\/code>, nếu x &gt; 1000 thì ném <code>out_of_range(\"qua lon\")<\/code>, còn lại trả về x·2. Nhập q số; với mỗi số chạy <code>async<\/code> rồi gọi <code>get()<\/code> trong try/catch: in kết quả, hoặc <code>Loi: <\/code> kèm <code>what()<\/code>.",tests:[{in:"4\n5\n-3\n2000\n0",out:"10\nLoi: so am\nLoi: qua lon\n0"},{in:"1\n1000",out:"2000"}],start:"#include <iostream>\n#include <future>\n#include <stdexcept>\nusing namespace std;\n\nint kiemTra(int x) {\n    return x * 2;\n}\nint main() {\n    int q;\n    cin >> q;\n    for (int i = 0; i < q; i++) {\n        int x;\n        cin >> x;\n        // auto f = async(launch::async, kiemTra, x); try { ... f.get() ... } catch ...\n    }\n    return 0;\n}",need:/async[\s\S]*try[\s\S]*\.get\s*\([\s\S]*catch/,needMsg:"Hãy gọi get() trong khối try và bắt ngoại lệ."}]);

